/* Original verse-by-verse Oneness study notes for the New Testament. */
window.verseCommentary = window.verseCommentary || {};
Object.assign(window.verseCommentary, {
  "Matthew 1:1": { title: "The Messianic Genealogy", text: "Matthew opens by identifying Jesus as Israel’s promised Messiah. “Son of David” points to the royal covenant; “son of Abraham” points to the promise that blessing would come to the nations through Abraham’s seed.", refs: ["Genesis 12:3","2 Samuel 7:12–16","Galatians 3:16"] },
  "Matthew 1:2": { title: "The Messianic Genealogy", text: "The genealogy places Jesus within the covenant history of Israel. Matthew presents the Messiah as the fulfillment of God’s promises, not as a detached figure unrelated to the biblical story.", refs: ["Genesis 21:3","25:26","29:35"] },
  "Matthew 1:3": { title: "The Messianic Genealogy", text: "Matthew preserves names that connect the Messiah’s family line to real human history, including Tamar. God’s redemptive purpose works through a complicated family history.", refs: ["Genesis 38:27–30","Ruth 4:18–22"] },
  "Matthew 1:4": { title: "The Messianic Genealogy", text: "The genealogy continues the record of the promised line. Its repeated pattern emphasizes continuity from the patriarchs toward the coming King.", refs: ["Ruth 4:20","1 Chronicles 2:10–11"] },
  "Matthew 1:5": { title: "The Messianic Genealogy", text: "Rahab and Ruth, women associated with the nations, appear in the Messiah’s genealogy. Matthew’s record anticipates the gospel’s reach beyond Israel.", refs: ["Joshua 2:1","Ruth 1:16","4:13–17"] },
  "Matthew 1:6": { title: "The Messianic Genealogy", text: "David’s kingship anchors Jesus’ royal claim, while the reference to Uriah recalls David’s grievous sin. The Messiah’s lineage shows God’s faithfulness despite human failure.", refs: ["2 Samuel 7:12–16","11:1–27","Psalm 132:11"] },
  "Matthew 1:7": { title: "The Messianic Genealogy", text: "The royal line proceeds through Judah’s kings. Their mixed history prepares readers to see the need for a righteous King greater than the flawed rulers before Him.", refs: ["1 Kings 11:43","14:21–31","15:1–8"] },
  "Matthew 1:8": { title: "The Messianic Genealogy", text: "Matthew traces the royal succession through generations of Judah. The genealogy is a theological record of the covenant line, not merely a list of famous names.", refs: ["1 Kings 15:9–24","22:41–50","2 Chronicles 21:1–20"] },
  "Matthew 1:9": { title: "The Messianic Genealogy", text: "The line includes kings remembered for very different responses to God. The promised Messiah arrives within Israel’s actual history and its repeated need for deliverance.", refs: ["2 Kings 15:32–38","16:1–20","18:1–7"] },
  "Matthew 1:10": { title: "The Messianic Genealogy", text: "Manasseh’s wicked reign and Josiah’s reforms show the spiritual contrasts within the royal line. Human kings fail, but God continues His purpose toward the Messiah.", refs: ["2 Kings 21:1–26","22:1–20"] },
  "Matthew 1:11": { title: "The Messianic Genealogy", text: "The exile marks a national judgment and a crisis for David’s kingdom. Matthew does not hide this dark period; it forms part of the history through which God preserved His promise.", refs: ["2 Kings 24:10–16","Jeremiah 22:24–30"] },
  "Matthew 1:12": { title: "The Messianic Genealogy", text: "The genealogy continues after the exile, showing that deportation did not erase God’s covenant purpose. Zerubbabel is associated with the return and rebuilding.", refs: ["Ezra 2:1–2","Haggai 2:20–23"] },
  "Matthew 1:13": { title: "The Messianic Genealogy", text: "These generations connect the post-exilic community to the Messiah’s arrival. Scripture sometimes preserves names for covenant continuity even when details of their lives are not given.", refs: ["1 Chronicles 3:19","Ezra 3:2"] },
  "Matthew 1:14": { title: "The Messianic Genealogy", text: "Matthew continues the line without assigning a separate narrative to every ancestor. Their inclusion reminds readers that God’s work spans generations beyond any one person’s lifetime.", refs: ["Luke 3:23–27"] },
  "Matthew 1:15": { title: "The Messianic Genealogy", text: "The genealogy moves toward Joseph and the birth narrative. Matthew is preparing to explain how Jesus belongs to David’s house while His conception is attributed to the Holy Ghost.", refs: ["Matthew 1:18–20"] },
  "Matthew 1:16": { title: "The Messianic Genealogy", text: "Matthew carefully calls Joseph Mary’s husband and says Jesus was born “of” Mary. This wording leads into the account of the virgin conception and identifies Jesus as the Christ.", refs: ["Matthew 1:18–25","Luke 1:26–35"] },
  "Matthew 1:17": { title: "The Messianic Genealogy", text: "Matthew arranges the genealogy in three groups of fourteen, giving the history a memorable structure. The focus is the movement of God’s promise from Abraham through David and exile to Christ.", refs: ["Genesis 12:1–3","2 Samuel 7:12–16"] },
  "Matthew 1:18": { title: "The Holy Ghost and the Conception of Jesus", text: "Matthew states that Mary conceived before marital union and attributes the conception to the Holy Ghost. The passage presents a miraculous human conception, not a second divine being becoming another God alongside the Father.", refs: ["Luke 1:35","John 1:14","1 Timothy 3:16"] },
  "Matthew 1:19": { title: "The Birth of Jesus Christ", text: "Joseph is portrayed as righteous and merciful. Before he understands the divine purpose, he seeks to avoid publicly shaming Mary.", refs: ["Deuteronomy 22:23–24","Luke 1:26–38"] },
  "Matthew 1:20": { title: "The Birth of Jesus Christ", text: "The angel confirms that Mary’s child is from the Holy Ghost and calls Joseph “son of David,” linking the child to the royal line through Joseph’s legal household. God Himself brings about the miraculous conception.", refs: ["Luke 1:35","Romans 1:3–4"] },
  "Matthew 1:21": { title: "Jesus: The Saviour", text: "The name Jesus is tied directly to His saving mission. In the Oneness reading, the one God saves His people through the real humanity He assumed in Christ; the name reveals God’s saving work among us.", refs: ["Psalm 130:7–8","Isaiah 43:11","Acts 4:12"] },
  "Matthew 1:22": { title: "The Birth of Jesus Christ", text: "Matthew explains the birth through prophetic fulfillment. The events are presented as God keeping His word, not as a later invention detached from Israel’s Scriptures.", refs: ["Isaiah 7:14","Matthew 2:5–6"] },
  "Matthew 1:23": { title: "Emmanuel: God With Us", text: "Emmanuel means “God with us.” From a Oneness perspective, this is a powerful statement of God’s presence in the man Christ Jesus: God came among humanity to save, rather than leaving humanity to reach Him unaided.", refs: ["Isaiah 7:14","John 1:14","2 Corinthians 5:19","1 Timothy 3:16"] },
  "Matthew 1:24": { title: "The Birth of Jesus Christ", text: "Joseph responds in obedience to the revelation he received. His action protects Mary and establishes the family setting into which Jesus is born.", refs: ["Matthew 1:20–23"] },
  "Matthew 1:25": { title: "The Birth of Jesus Christ", text: "Matthew affirms that Joseph did not have marital relations with Mary before Jesus’ birth and that he obeyed the instruction to name the child Jesus. The account emphasizes the extraordinary conception and the child’s saving identity.", refs: ["Luke 2:21","Galatians 4:4"] }
});
Object.assign(window.verseCommentary, {
  "Matthew 2:1": { title: "The Wise Men and the Promised King", text: "Jesus is born in Bethlehem, David’s city, during Herod’s reign. Gentile visitors begin seeking the Jewish Messiah, anticipating the good news reaching the nations.", refs: ["Micah 5:2","Isaiah 60:1–6"] },
  "Matthew 2:2": { title: "The Wise Men and the Promised King", text: "The wise men recognize a royal sign and come to honor the child. Their question contrasts with Herod’s insecurity and shows that Jesus’ kingship is not confined to local political expectations.", refs: ["Numbers 24:17","Matthew 2:7–11"] },
  "Matthew 2:3": { title: "The Wise Men and the Promised King", text: "Herod sees the report as a threat to his rule. The coming of God’s promised King exposes the conflict between self-protective power and God’s purpose.", refs: ["Psalm 2:1–6","John 19:12–15"] },
  "Matthew 2:4": { title: "The Wise Men and the Promised King", text: "Herod consults Scripture experts to locate the Messiah. Knowing the text, however, is not the same as submitting to what God has revealed.", refs: ["Micah 5:2","John 5:39–40"] },
  "Matthew 2:5": { title: "The Wise Men and the Promised King", text: "The leaders correctly identify Bethlehem from prophecy. Scripture gives a concrete location for the promised ruler, grounding Matthew’s account in Israel’s prophetic hope.", refs: ["Micah 5:2","John 7:42"] },
  "Matthew 2:6": { title: "The Wise Men and the Promised King", text: "The promised ruler comes from Bethlehem and shepherds Israel. Jesus’ authority fulfills the expectation of a ruler whose significance comes from God’s promise, not earthly prestige.", refs: ["Micah 5:2–4","John 10:11"] },
  "Matthew 2:7": { title: "Worship and Warning", text: "Herod seeks information secretly, not to worship Jesus but to protect his throne. The verse exposes the difference between sincere seeking and manipulative religious language.", refs: ["Matthew 2:8, 13"] },
  "Matthew 2:8": { title: "Worship and Warning", text: "Herod’s claim to worship is deceptive. The narrative warns that outward religious words can conceal resistance to God’s will.", refs: ["Matthew 2:16","Psalm 5:6"] },
  "Matthew 2:9": { title: "Worship and Warning", text: "The wise men continue their journey, guided to the child. Matthew presents divine guidance as directing sincere seekers toward Jesus.", refs: ["Numbers 24:17","Luke 2:8–12"] },
  "Matthew 2:10": { title: "Worship and Warning", text: "Their joy is a response to being led to the promised King. The passage presents seeking Jesus as a cause for gladness rather than fear.", refs: ["Luke 2:10–11","Philippians 4:4"] },
  "Matthew 2:11": { title: "Worship and Warning", text: "The wise men bow before Jesus and offer costly gifts. Matthew portrays the child as worthy of honor; in a Oneness reading, worship of Jesus is consistent with God’s own presence and fullness revealed in Him.", refs: ["Isaiah 60:3, 6","Matthew 1:23","Colossians 2:9"] },
  "Matthew 2:12": { title: "Worship and Warning", text: "God protects the child by warning the wise men. Their obedience prevents Herod from using them to find Jesus.", refs: ["Matthew 2:13","Acts 5:29"] },
  "Matthew 2:13": { title: "God Preserves the Child", text: "Joseph receives urgent direction to protect Jesus from Herod. The Messiah enters real danger and experiences displacement in His humanity; God’s plan unfolds amid hostile rulers.", refs: ["Hosea 11:1","Matthew 2:16"] },
  "Matthew 2:14": { title: "God Preserves the Child", text: "Joseph obeys immediately, traveling at night to protect the family. Faith is shown in action, especially when obedience requires sacrifice and uncertainty.", refs: ["Matthew 1:24","Matthew 2:20–21"] },
  "Matthew 2:15": { title: "God Preserves the Child", text: "Matthew applies Hosea’s words to Jesus, presenting Him as embodying Israel’s story and fulfilling God’s purpose. The title “my son” identifies Jesus in His messianic humanity and mission.", refs: ["Hosea 11:1","Exodus 4:22–23"] },
  "Matthew 2:16": { title: "Herod’s Violence and Prophetic Sorrow", text: "Herod’s rage leads to horrific violence against children. Scripture does not disguise the cruelty of political power threatened by God’s purposes; Jesus’ early life is marked by danger and grief.", refs: ["Jeremiah 31:15","Matthew 2:13"] },
  "Matthew 2:17": { title: "Herod’s Violence and Prophetic Sorrow", text: "Matthew connects the suffering of Bethlehem’s families with Jeremiah’s image of Rachel weeping. Fulfillment language can describe a pattern in Israel’s history reaching a fuller expression in the Messiah’s time.", refs: ["Jeremiah 31:15"] },
  "Matthew 2:18": { title: "Herod’s Violence and Prophetic Sorrow", text: "The prophecy gives voice to the anguish caused by Herod’s massacre. The Bible records grief honestly and does not pretend that God’s redemptive work makes human suffering unreal.", refs: ["Jeremiah 31:15–17","Romans 12:15"] },
  "Matthew 2:19": { title: "Return and the Nazarene", text: "After Herod’s death, God again directs Joseph. The ruler who threatened Jesus does not have the final word over God’s plan.", refs: ["Matthew 2:13","Acts 12:23–24"] },
  "Matthew 2:20": { title: "Return and the Nazarene", text: "Joseph is told that the immediate threat has passed. The wording echoes the biblical account of Moses, creating a pattern of a threatened deliverer preserved from a murderous ruler.", refs: ["Exodus 4:19","Matthew 2:16"] },
  "Matthew 2:21": { title: "Return and the Nazarene", text: "Joseph again obeys the divine instruction. The family returns as God directs, continuing the fulfillment narrative.", refs: ["Matthew 2:19–20"] },
  "Matthew 2:22": { title: "Return and the Nazarene", text: "Joseph acts with caution and receives further guidance. Trusting God does not require ignoring danger; the narrative joins obedience with prudent action.", refs: ["Matthew 2:13, 19–22"] },
  "Matthew 2:23": { title: "Return and the Nazarene", text: "Jesus grows up in Nazareth, a place without obvious royal prestige. Matthew’s wording refers broadly to the prophets rather than quoting one exact sentence, emphasizing the Messiah’s humble and rejected status.", refs: ["Isaiah 11:1","Isaiah 53:2–3","John 1:46"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 3:1": { title: "John Prepares the Way", text: "John appears as the promised forerunner, calling Israel to prepare for the Lord’s arrival. His wilderness ministry echoes the prophets’ call to return to God.", refs: ["Isaiah 40:3","Malachi 3:1"] },
  "Matthew 3:2": { title: "John Prepares the Way", text: "Repentance means turning from sin toward God. The kingdom is near because God’s promised King and saving work are being revealed in Jesus.", refs: ["Matthew 4:17","Mark 1:15"] },
  "Matthew 3:3": { title: "John Prepares the Way", text: "Matthew identifies John with Isaiah’s voice preparing the way of the Lord. This prepares readers for the striking New Testament witness that God’s coming is revealed in Jesus.", refs: ["Isaiah 40:3","Luke 1:76","John 1:23"] },
  "Matthew 3:4": { title: "Repentance and the Coming Messiah", text: "John’s clothing and simple food recall the prophetic style associated with Elijah. His life emphasizes the urgency of his message rather than status or luxury.", refs: ["2 Kings 1:8","Matthew 11:13–14"] },
  "Matthew 3:5": { title: "Repentance and the Coming Messiah", text: "John’s message draws people from a wide region. The response shows that many were seeking spiritual renewal, though their response must be tested by lasting repentance.", refs: ["Mark 1:5","Luke 3:7–14"] },
  "Matthew 3:6": { title: "Repentance and the Coming Messiah", text: "Baptism accompanied confession and repentance. John’s baptism prepared people for the One who would bring the fuller work of the Spirit.", refs: ["Acts 19:3–5","Matthew 3:11"] },
  "Matthew 3:7": { title: "Repentance and the Coming Messiah", text: "John warns religious leaders not to rely on position or appearance. God calls for genuine repentance, not merely participation in a religious ceremony.", refs: ["Luke 3:7–9","Romans 2:28–29"] },
  "Matthew 3:8": { title: "Repentance and the Coming Messiah", text: "Repentance should produce visible fruit in conduct. A changed confession that leaves injustice and sin untouched does not match John’s demand.", refs: ["Luke 3:10–14","Galatians 5:22–23"] },
  "Matthew 3:9": { title: "Repentance and the Coming Messiah", text: "Ethnic descent cannot replace personal faithfulness to God. God’s promise is not controlled by human pride or ancestry.", refs: ["John 8:39–40","Romans 9:6–8"] },
  "Matthew 3:10": { title: "Repentance and the Coming Messiah", text: "John’s warning is urgent: God judges fruitless lives. The image calls hearers to respond now rather than presume on religious privilege.", refs: ["Matthew 7:19","Luke 13:6–9"] },
  "Matthew 3:11": { title: "Repentance and the Coming Messiah", text: "John distinguishes his water baptism from the greater work of the coming Messiah. Jesus is the giver of the promised Holy Ghost, central to the new-covenant experience.", refs: ["Joel 2:28–29","John 1:33","Acts 2:1–4"] },
  "Matthew 3:12": { title: "Repentance and the Coming Messiah", text: "The Messiah brings both gathering and judgment. The image warns that His coming demands a real response and that God distinguishes fruitful faith from empty profession.", refs: ["Malachi 3:2–3","Matthew 13:30"] },
  "Matthew 3:13": { title: "Jesus Comes to Be Baptized", text: "Jesus comes to John voluntarily. His baptism does not mean He confesses personal sin; it introduces His public ministry and His identification with the people He came to save.", refs: ["Luke 3:21–23","Hebrews 4:15"] },
  "Matthew 3:14": { title: "Jesus Comes to Be Baptized", text: "John recognizes Jesus’ superiority and is surprised that Jesus seeks baptism from him. The scene underscores Jesus’ humility and John’s witness to His greater identity.", refs: ["John 1:26–27","John 1:29–30"] },
  "Matthew 3:15": { title: "Jesus Comes to Be Baptized", text: "Jesus says the baptism is fitting to fulfill righteousness. He obediently enters the path appointed by God and identifies with those He came to redeem.", refs: ["Psalm 40:7–8","Luke 7:29–30"] },
  "Matthew 3:16": { title: "The Spirit and the Heavenly Witness", text: "The Spirit descends upon Jesus as He begins His public ministry. The scene distinguishes Jesus’ human life and the Spirit’s visible sign without requiring three divine beings; the passage presents God’s action and revelation at Jesus’ baptism.", refs: ["Isaiah 11:2","Luke 3:22","John 1:32–34"] },
  "Matthew 3:17": { title: "The Spirit and the Heavenly Witness", text: "The heavenly voice publicly identifies Jesus as the beloved Son and echoes royal and servant prophecies. In Oneness teaching, “Son” refers to the genuine incarnation and messianic identity, while God remains one.", refs: ["Psalm 2:7","Isaiah 42:1","Luke 1:35"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 4:1": { title: "Jesus Overcomes Temptation", text: "Jesus enters a real period of testing under the Spirit’s leading. His victory as the obedient man contrasts with humanity’s repeated failure.", refs: ["Hebrews 2:18","4:15"] },
  "Matthew 4:2": { title: "Jesus Overcomes Temptation", text: "Jesus’ hunger confirms the reality of His humanity. The incarnate Lord experienced physical need rather than merely appearing human.", refs: ["Exodus 34:28","Hebrews 2:14–17"] },
  "Matthew 4:3": { title: "Jesus Overcomes Temptation", text: "The temptation challenges Jesus to use power apart from obedient trust. His sonship is not proved by self-serving spectacle but by faithfulness to the Father’s purpose.", refs: ["Deuteronomy 8:3","Matthew 27:40"] },
  "Matthew 4:4": { title: "Jesus Overcomes Temptation", text: "Jesus answers with Scripture, teaching that obedience to God’s word matters more than immediate appetite. He succeeds where Israel had been tested in the wilderness.", refs: ["Deuteronomy 8:3","John 6:35"] },
  "Matthew 4:5": { title: "Jesus Overcomes Temptation", text: "The next temptation uses a sacred location and a religious challenge. Being near holy things does not make a temptation holy.", refs: ["Psalm 91:11–12","Luke 4:9"] },
  "Matthew 4:6": { title: "Jesus Overcomes Temptation", text: "The devil quotes Scripture while distorting its purpose. Biblical words must be read faithfully, not used to demand that God prove Himself through reckless action.", refs: ["Psalm 91:11–12","2 Peter 3:16"] },
  "Matthew 4:7": { title: "Jesus Overcomes Temptation", text: "Jesus refuses to manipulate God or demand a sign. Trust rests in obedience, not in forcing God to intervene on our terms.", refs: ["Deuteronomy 6:16","Exodus 17:1–7"] },
  "Matthew 4:8": { title: "Jesus Overcomes Temptation", text: "The final temptation offers worldly power without the path of obedience and suffering. Jesus rejects a kingdom gained through allegiance to evil.", refs: ["Psalm 2:8","John 18:36"] },
  "Matthew 4:9": { title: "Jesus Overcomes Temptation", text: "Satan demands worship in exchange for power. The offer exposes the idolatry beneath ambition that places anything above God.", refs: ["Exodus 20:3–5","Luke 4:6–7"] },
  "Matthew 4:10": { title: "Jesus Overcomes Temptation", text: "Jesus answers that worship and service belong to God alone. This is consistent with the Bible’s uncompromising confession that the Lord is one.", refs: ["Deuteronomy 6:4, 13","Matthew 22:37"] },
  "Matthew 4:11": { title: "Jesus Overcomes Temptation", text: "After Jesus’ victory, angels minister to Him. The account shows that temptation can be endured through faithful reliance on God’s word.", refs: ["Hebrews 1:14","James 4:7"] },
  "Matthew 4:12": { title: "The Light in Galilee", text: "John’s imprisonment marks a dangerous turn, and Jesus begins His Galilean ministry. God’s work continues even when faithful witnesses are persecuted.", refs: ["Matthew 14:3–5","Mark 1:14"] },
  "Matthew 4:13": { title: "The Light in Galilee", text: "Jesus makes Capernaum a base for ministry in Galilee. Matthew highlights the location because it connects Jesus’ work with Isaiah’s prophecy.", refs: ["Isaiah 9:1–2","Matthew 9:1"] },
  "Matthew 4:14": { title: "The Light in Galilee", text: "Matthew explicitly frames Jesus’ ministry as fulfillment of the prophetic Scriptures. The light appearing in Galilee is part of God’s promised deliverance.", refs: ["Isaiah 9:1–2"] },
  "Matthew 4:15": { title: "The Light in Galilee", text: "Galilee’s mixed population and history make the prophecy’s mention of Gentiles significant. The Messiah’s light reaches beyond the center of religious power.", refs: ["Isaiah 9:1","Luke 2:32"] },
  "Matthew 4:16": { title: "The Light in Galilee", text: "Jesus is presented as the promised light to people living in spiritual darkness. In Him, God brings revelation, healing, and salvation near.", refs: ["Isaiah 9:2","John 1:4–9","John 8:12"] },
  "Matthew 4:17": { title: "The Light in Galilee", text: "Jesus begins with the same urgent call John preached: repent, because God’s kingdom is near. The kingdom arrives through the King’s presence and work.", refs: ["Matthew 3:2","Mark 1:15"] },
  "Matthew 4:18": { title: "The Call and Ministry of Jesus", text: "Jesus calls ordinary working people to follow Him. Discipleship begins with His initiative and reshapes a person’s daily life around His mission.", refs: ["Luke 5:1–11","John 1:40–42"] },
  "Matthew 4:19": { title: "The Call and Ministry of Jesus", text: "Jesus promises to transform their work into a mission of gathering people. Following Him means learning His ways and participating in His saving purpose.", refs: ["Jeremiah 16:16","Acts 2:38–41"] },
  "Matthew 4:20": { title: "The Call and Ministry of Jesus", text: "Their immediate response models decisive obedience. The call of Jesus can require leaving familiar security to serve His purpose.", refs: ["Matthew 10:37–39","Luke 14:26–33"] },
  "Matthew 4:21": { title: "The Call and Ministry of Jesus", text: "Jesus calls another pair of brothers in the middle of ordinary work and family life. Discipleship reaches people where they are and calls them into a new priority.", refs: ["Mark 1:19–20"] },
  "Matthew 4:22": { title: "The Call and Ministry of Jesus", text: "James and John respond with urgency. The verse emphasizes the seriousness of Jesus’ call, though discipleship is not a command to neglect every family duty in every circumstance.", refs: ["Matthew 10:37","1 Timothy 5:8"] },
  "Matthew 4:23": { title: "The Call and Ministry of Jesus", text: "Jesus’ ministry joins teaching, proclamation, and healing. His works reveal God’s compassion and authority, while His message announces the kingdom.", refs: ["Isaiah 35:5–6","Luke 4:18–21"] },
  "Matthew 4:24": { title: "The Call and Ministry of Jesus", text: "People from surrounding regions bring many kinds of suffering to Jesus. Matthew presents His authority as extending over physical illness and demonic oppression; the language reflects the descriptions used in the passage.", refs: ["Matthew 8:16–17","Acts 10:38"] },
  "Matthew 4:25": { title: "The Call and Ministry of Jesus", text: "Crowds from a broad region gather around Jesus. This prepares for the Sermon on the Mount, where the King teaches what life under God’s reign looks like.", refs: ["Matthew 5:1–2","Luke 6:17–19"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 5:1": { title: "The Beatitudes", text: "Jesus sits as a teacher and addresses His disciples, with the crowds also in view. The Sermon on the Mount describes the character and conduct of life under God’s kingdom.", refs: ["Matthew 7:28–29","Luke 6:17–20"] },
  "Matthew 5:2": { title: "The Beatitudes", text: "Matthew introduces an extended teaching of Jesus. His words carry authority and explain righteousness from the heart outward.", refs: ["Matthew 7:24–27"] },
  "Matthew 5:3": { title: "The Beatitudes", text: "Those who know their spiritual need and depend on God are blessed. Kingdom life begins with humility, not self-sufficiency.", refs: ["Isaiah 57:15","James 4:6"] },
  "Matthew 5:4": { title: "The Beatitudes", text: "Jesus promises God’s comfort to those who grieve, including those who mourn sin and the brokenness of the world.", refs: ["Isaiah 61:1–3","Revelation 21:4"] },
  "Matthew 5:5": { title: "The Beatitudes", text: "Meekness is humble strength submitted to God, not weakness or indifference. Jesus promises the inheritance God has pledged to His people.", refs: ["Psalm 37:11","Matthew 11:29"] },
  "Matthew 5:6": { title: "The Beatitudes", text: "God blesses those who deeply desire what is right. The promise encourages persistent pursuit of God’s will and justice.", refs: ["Psalm 42:1–2","Isaiah 55:1–2"] },
  "Matthew 5:7": { title: "The Beatitudes", text: "Those who have received mercy should show mercy to others. Mercy is a mark of kingdom character, not permission to call evil good.", refs: ["James 2:13","Luke 6:36"] },
  "Matthew 5:8": { title: "The Beatitudes", text: "God desires inward purity as well as outward obedience. A sincere heart seeks God rather than merely appearing religious.", refs: ["Psalm 24:3–4","Hebrews 12:14"] },
  "Matthew 5:9": { title: "The Beatitudes", text: "Peacemakers actively pursue reconciliation and truth. They reflect the character of the God who brings people back to Himself.", refs: ["Romans 12:18","2 Corinthians 5:18–20"] },
  "Matthew 5:10": { title: "The Beatitudes", text: "Faithfulness to God can bring opposition. Jesus assures His followers that persecution does not mean God has abandoned them.", refs: ["2 Timothy 3:12","1 Peter 3:14"] },
  "Matthew 5:11": { title: "Salt and Light", text: "Jesus blesses those falsely accused because of Him. The condition matters: this is not praise for wrongdoing but encouragement amid unjust hostility.", refs: ["1 Peter 4:14–16"] },
  "Matthew 5:12": { title: "Salt and Light", text: "Jesus places present suffering within the larger story of God’s faithful servants. The prophets also faced rejection for speaking God’s word.", refs: ["2 Chronicles 36:16","Hebrews 11:32–38"] },
  "Matthew 5:13": { title: "Salt and Light", text: "Disciples should preserve what is good and make a distinct difference in the world. Losing that distinctiveness makes their witness ineffective.", refs: ["Mark 9:50","Colossians 4:6"] },
  "Matthew 5:14": { title: "Salt and Light", text: "Jesus calls His followers to visible faithfulness. Their lives should point others toward God rather than conceal the truth they have received.", refs: ["Philippians 2:15","John 8:12"] },
  "Matthew 5:15": { title: "Salt and Light", text: "A light is meant to shine where it can help others. Disciples should not hide their witness out of fear or desire for comfort.", refs: ["Luke 8:16","Mark 4:21"] },
  "Matthew 5:16": { title: "Salt and Light", text: "Good works should direct praise to the Father, not inflate the disciple’s ego. Visible conduct can make God’s goodness known.", refs: ["1 Peter 2:12","Ephesians 2:10"] },
  "Matthew 5:17": { title: "Jesus and the Law", text: "Jesus does not present His mission as rejecting Scripture. He fulfills its purpose and brings its promises to their intended realization.", refs: ["Luke 24:27","Romans 3:31"] },
  "Matthew 5:18": { title: "Jesus and the Law", text: "Jesus affirms the seriousness and enduring authority of God’s word. His fulfillment must be understood through His teaching and completed mission.", refs: ["Luke 16:17","Matthew 24:35"] },
  "Matthew 5:19": { title: "Jesus and the Law", text: "Jesus warns against carelessly dismissing God’s commands while teaching others to do likewise. Discipleship requires both practice and teaching consistent with God’s will.", refs: ["James 1:22","Matthew 23:2–3"] },
  "Matthew 5:20": { title: "Jesus and the Law", text: "Kingdom righteousness goes deeper than public religious performance. Jesus will show that obedience includes motives, desires, and treatment of others.", refs: ["Matthew 23:25–28","Romans 2:28–29"] },
  "Matthew 5:21": { title: "Reconciliation and Anger", text: "Jesus begins to expose the heart behind the command against murder. He does not lessen the command but addresses the anger and contempt that can lead toward harm.", refs: ["Exodus 20:13","1 John 3:15"] },
  "Matthew 5:22": { title: "Reconciliation and Anger", text: "Contemptuous anger and degrading speech are serious matters before God. Jesus calls His followers to deal with hostility before it grows into destructive action.", refs: ["Ephesians 4:26–32","James 1:19–20"] },
  "Matthew 5:23": { title: "Reconciliation and Anger", text: "Worship cannot be separated from responsibility toward others. If a relationship is damaged, the worshipper should take that matter seriously.", refs: ["Isaiah 1:13–17","1 John 4:20"] },
  "Matthew 5:24": { title: "Reconciliation and Anger", text: "Jesus commands active pursuit of reconciliation before continuing the offering. Seeking peace is part of honoring God, though reconciliation may still require wisdom and safety.", refs: ["Romans 12:18","Matthew 18:15"] },
  "Matthew 5:25": { title: "Reconciliation and Anger", text: "Jesus urges prompt settlement before a dispute escalates into judgment and loss. The principle is to pursue a just resolution while there is opportunity.", refs: ["Proverbs 25:8–10","Luke 12:58–59"] },
  "Matthew 5:26": { title: "Purity and Marriage", text: "Jesus turns from murder to sexual faithfulness, showing that God’s moral will concerns more than outward acts.", refs: ["Exodus 20:14","Hebrews 13:4"] },
  "Matthew 5:27": { title: "Purity and Marriage", text: "Jesus condemns deliberately cultivated lust, not merely the accidental noticing of someone. Faithfulness begins in the heart and calls for guarding desire.", refs: ["Job 31:1","2 Timothy 2:22"] },
  "Matthew 5:28": { title: "Purity and Marriage", text: "This vivid figure teaches decisive action against sin; it is not a command to injure oneself. Remove access, habits, or situations that feed destructive desire.", refs: ["Colossians 3:5","Romans 13:14"] },
  "Matthew 5:29": { title: "Purity and Marriage", text: "Jesus stresses the seriousness of sin through hyperbole. Disciples must be willing to sacrifice convenience rather than continue in what destroys them.", refs: ["Matthew 18:8–9","Mark 9:43–47"] },
  "Matthew 5:30": { title: "Purity and Marriage", text: "Jesus addresses divorce and challenges casual dismissal of marriage. The surrounding teaching must be read with the rest of Scripture on covenant faithfulness and human hardness of heart.", refs: ["Deuteronomy 24:1–4","Matthew 19:3–9"] },
  "Matthew 5:31": { title: "Purity and Marriage", text: "Jesus condemns treating marriage as disposable and names sexual immorality in this exception. The passage calls for careful, compassionate application rather than using divorce as a casual option.", refs: ["Matthew 19:3–9","Mark 10:11–12"] },
  "Matthew 5:32": { title: "Truthful Speech", text: "Jesus addresses truthfulness and oath-taking. Religious promises do not excuse dishonesty in ordinary speech.", refs: ["Leviticus 19:12","Numbers 30:2"] },
  "Matthew 5:33": { title: "Truthful Speech", text: "Jesus forbids using sacred things to give false weight to one’s words. His followers should speak truthfully without manipulative oath formulas.", refs: ["James 5:12","Isaiah 66:1"] },
  "Matthew 5:34": { title: "Truthful Speech", text: "Earth and Jerusalem belong to God, so they cannot be used as props for deceptive speech. All creation is under God’s authority.", refs: ["Psalm 48:2","Isaiah 66:1"] },
  "Matthew 5:35": { title: "Truthful Speech", text: "Human beings do not control even the smallest details of their lives. Humility should shape speech and discourage exaggerated claims of control.", refs: ["Luke 12:25–26"] },
  "Matthew 5:36": { title: "Truthful Speech", text: "Jesus calls for plain, dependable truth. A disciple’s ordinary yes or no should be trustworthy without elaborate guarantees.", refs: ["James 5:12","Ephesians 4:25"] },
  "Matthew 5:37": { title: "Mercy Instead of Retaliation", text: "The original law limited retaliation and restrained disproportionate punishment. Jesus now teaches His disciples not to be ruled by personal vengeance.", refs: ["Exodus 21:24","Leviticus 24:19–20"] },
  "Matthew 5:38": { title: "Mercy Instead of Retaliation", text: "Jesus rejects retaliatory revenge and calls for a response that breaks the cycle of insult. This is not a demand to enable abuse or abandon lawful protection in every situation.", refs: ["Romans 12:17–21","John 18:22–23"] },
  "Matthew 5:39": { title: "Mercy Instead of Retaliation", text: "Jesus illustrates a radical willingness to surrender personal advantage rather than be governed by spite. The example challenges possessiveness and vindictiveness.", refs: ["1 Corinthians 6:7","Romans 12:18"] },
  "Matthew 5:40": { title: "Mercy Instead of Retaliation", text: "Under coercion, Jesus teaches a surprising generosity that refuses to let the oppressor dictate the disciple’s spirit. The principle is willing service beyond bare compulsion.", refs: ["Matthew 27:32","Romans 12:20"] },
  "Matthew 5:41": { title: "Love Your Enemies", text: "Jesus calls His followers to generosity and compassion. Giving should be guided by wisdom and genuine need, not by indifference to the vulnerable.", refs: ["Deuteronomy 15:7–11","Luke 6:30–36"] },
  "Matthew 5:42": { title: "Love Your Enemies", text: "The command to love one’s neighbour is biblical, but hatred of enemies is not commanded by the law. Jesus corrects the restricted understanding of neighbour-love.", refs: ["Leviticus 19:18","Proverbs 25:21–22"] },
  "Matthew 5:43": { title: "Love Your Enemies", text: "Jesus commands active love toward enemies: blessing, doing good, and prayer. This does not call evil good; it refuses to answer hatred with hatred.", refs: ["Luke 6:27–28","Romans 12:14"] },
  "Matthew 5:44": { title: "Love Your Enemies", text: "God shows common kindness even to those who do wrong. His people should reflect this generous character rather than love only those who agree with them.", refs: ["Acts 14:16–17","Luke 6:35"] },
  "Matthew 5:45": { title: "Love Your Enemies", text: "Love limited to those who return it is not distinctive. Jesus calls for a generosity that exceeds ordinary reciprocity.", refs: ["Luke 6:32–34"] },
  "Matthew 5:46": { title: "Love Your Enemies", text: "Disciples must not reserve kindness only for their own circle. God’s kingdom forms a people whose conduct shows a wider love.", refs: ["Galatians 6:10","James 2:1–4"] },
  "Matthew 5:47": { title: "Love Your Enemies", text: "In context, “perfect” carries the sense of completeness or maturity, especially in the all-embracing love just described. Jesus calls His disciples to reflect the Father’s generous character.", refs: ["Luke 6:36","Leviticus 19:2"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 5:48": { title: "Love That Reflects the Father", text: "In context, “perfect” carries the sense of completeness or maturity, especially in the all-embracing love Jesus has just commanded. The disciple is called to reflect the Father’s generous character, loving beyond the limits of reciprocity.", refs: ["Luke 6:36", "Leviticus 19:2"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 6:1": { title: "Giving to Be Seen by God", text: "Jesus warns against giving for public applause. Righteous acts should flow from devotion to God, not from a desire to build a religious reputation.", refs: ["Matthew 23:5","2 Corinthians 9:7"] },
  "Matthew 6:2": { title: "The Secret Place of Giving", text: "The Father sees what people do not see. Secret generosity trains the heart to seek God's approval rather than human praise.", refs: ["Luke 14:13–14","Hebrews 4:13"] },
  "Matthew 6:3": { title: "Prayer Without Performance", text: "Jesus contrasts sincere prayer with public performance. The issue is not praying where others can hear, but using prayer to gain status.", refs: ["Luke 18:10–14","Matthew 23:14"] },
  "Matthew 6:4": { title: "Pray to the Father in Secret", text: "Private prayer expresses a real relationship with God. Jesus directs His disciples to seek the Father sincerely, without turning devotion into a show.", refs: ["Psalm 91:1","Matthew 6:6"] },
  "Matthew 6:5": { title: "Avoid Empty Repetition", text: "Jesus condemns empty, mechanical repetition as though many words could force God to answer. Persistent prayer elsewhere in Scripture is different from meaningless verbosity.", refs: ["1 Kings 18:26–29","Luke 18:1–8"] },
  "Matthew 6:6": { title: "The Father Knows Your Needs", text: "God already knows what His children need before they ask. Prayer is not informing an ignorant deity; it is trusting and depending on the Father.", refs: ["Psalm 139:1–4","Romans 8:26–27"] },
  "Matthew 6:7": { title: "The Lord's Prayer: Our Father", text: "Jesus teaches a model prayer beginning with reverence and relationship. The one God is addressed as Father, and His name is to be honored.", refs: ["Deuteronomy 6:4","Isaiah 64:8"] },
  "Matthew 6:8": { title: "Hallowed Be Thy Name", text: "God's name is holy and must be treated with reverence. Prayer begins with God's honor, not merely the worshipper's requests.", refs: ["Leviticus 22:32","Ezekiel 36:23"] },
  "Matthew 6:9": { title: "Thy Kingdom Come", text: "The disciple asks for God's reign and purposes to be manifested. The prayer looks beyond personal interests toward God's will on earth.", refs: ["Matthew 4:17","Revelation 11:15"] },
  "Matthew 6:10": { title: "Thy Will Be Done", text: "Jesus teaches surrender to the Father's will. His own prayer in Gethsemane later demonstrates this obedience in the face of suffering.", refs: ["Matthew 26:39","1 John 5:14"] },
  "Matthew 6:11": { title: "Daily Bread", text: "The prayer asks God for daily provision and teaches dependence rather than anxious self-sufficiency. It also reminds disciples to care for people who lack food.", refs: ["Proverbs 30:8","James 2:15–16"] },
  "Matthew 6:12": { title: "Forgive Us Our Debts", text: "The prayer acknowledges sin as a debt needing forgiveness. Disciples approach God humbly and must also be ready to forgive those who wrong them.", refs: ["Psalm 32:1–5","Ephesians 4:32"] },
  "Matthew 6:13": { title: "Lead Us Not into Temptation", text: "This petition asks for God's guidance and protection from testing that could lead to failure. It does not imply God entices people to sin.", refs: ["Matthew 26:41","James 1:13–14"] },
  "Matthew 6:14": { title: "The Kingdom, Power, and Glory", text: "Many KJV editions include this closing doxology, while some ancient manuscripts omit it. Its words rightly ascribe the kingdom, power, and glory to God.", refs: ["1 Chronicles 29:11","Revelation 5:13"] },
  "Matthew 6:15": { title: "Forgiveness and the Forgiving Heart", text: "Jesus stresses that receiving God's mercy must change how we treat others. Forgiveness does not call evil good or remove every need for justice and boundaries.", refs: ["Matthew 18:21–35","Colossians 3:13"] },
  "Matthew 6:16": { title: "Fasting Without Display", text: "Fasting should not be performed to win admiration. Jesus calls for sincerity before God rather than a public display of spiritual discipline.", refs: ["Isaiah 58:3–7","Acts 13:2–3"] },
  "Matthew 6:17": { title: "God Sees Secret Devotion", text: "The Father sees devotion that people may never notice. The promise encourages sincerity rather than a guaranteed material reward for every act.", refs: ["Matthew 6:4–6","Hebrews 11:6"] },
  "Matthew 6:18": { title: "Treasures on Earth", text: "Earthly possessions are vulnerable to decay, theft, and loss. Jesus warns against making temporary things the foundation of life.", refs: ["Proverbs 23:4–5","1 Timothy 6:17"] },
  "Matthew 6:19": { title: "Treasures in Heaven", text: "Heavenly treasure is connected with faithful obedience and generosity. Jesus redirects the heart toward what has lasting value before God.", refs: ["Matthew 19:21","1 Timothy 6:18–19"] },
  "Matthew 6:20": { title: "Where Your Treasure Is", text: "A person's priorities reveal the direction of the heart. What we value most shapes our choices, loyalties, and use of resources.", refs: ["Luke 12:34","Colossians 3:1–2"] },
  "Matthew 6:21": { title: "The Eye as the Lamp", text: "Jesus uses the eye as an image of inner focus. A generous, clear outlook affects how a person sees life; envy and greed darken that outlook.", refs: ["Luke 11:34–36","Proverbs 28:22"] },
  "Matthew 6:22": { title: "Light or Darkness Within", text: "If the inner outlook is corrupted, a person may mistake darkness for light. Spiritual self-deception is especially dangerous when greed is called blessing.", refs: ["John 9:39–41","Ephesians 5:8–13"] },
  "Matthew 6:23": { title: "No One Can Serve Two Masters", text: "God and wealth cannot both hold ultimate allegiance. Money can be a tool, but it must not become the master that governs worship and obedience.", refs: ["Joshua 24:15","Luke 16:13"] },
  "Matthew 6:24": { title: "Do Not Be Anxiously Distracted", text: "Jesus teaches against consuming anxiety over food, drink, and clothing. He is not forbidding responsible work; He is calling for trust in God's care.", refs: ["Philippians 4:6–7","1 Peter 5:7"] },
  "Matthew 6:25": { title: "Life Is More Than Food", text: "Human life has value beyond material survival and possessions. Jesus invites disciples to trust the Creator who gave life itself.", refs: ["Luke 12:22–23","Deuteronomy 8:3"] },
  "Matthew 6:26": { title: "Consider the Birds", text: "Birds do not store up provisions as humans do, yet God sustains them. Jesus uses creation to challenge anxious distrust, not to excuse idleness.", refs: ["Psalm 147:9","2 Thessalonians 3:10"] },
  "Matthew 6:27": { title: "Anxiety Cannot Add to Life", text: "Worry cannot extend life or grant control over the future. Jesus calls His disciples to recognize the limits of human control and trust God.", refs: ["Psalm 39:5","Luke 12:25–26"] },
  "Matthew 6:28": { title: "Consider the Lilies", text: "The beauty of the flowers illustrates God's provision. Even Solomon's royal clothing did not surpass the splendor God gives to ordinary creation.", refs: ["1 Kings 10:4–7","Psalm 104:24"] },
  "Matthew 6:29": { title: "God Clothes the Grass", text: "If God clothes temporary grass, He is able to care for His people. Jesus identifies anxiety as a sign of little faith, inviting renewed trust.", refs: ["Isaiah 40:6–8","Luke 12:28"] },
  "Matthew 6:30": { title: "Seek God's Kingdom First", text: "The priority is God's kingdom and righteousness. This is not a promise of luxury, but an assurance that the Father knows and cares for His people's needs.", refs: ["Psalm 37:4–7","Matthew 5:6"] },
  "Matthew 6:31": { title: "Do Not Borrow Tomorrow's Trouble", text: "Jesus directs disciples to face each day's responsibilities without carrying tomorrow's imagined burdens in advance. This is trustful living, not denial of future planning.", refs: ["Exodus 16:4–5","Philippians 4:11–12"] }
});

Object.assign(window.verseCommentary, {
  "Matthew 6:13": { title: "Prayer for Deliverance", text: "Jesus’ model prayer asks for protection from temptation and deliverance from evil. The familiar closing doxology appears in many KJV editions; some ancient manuscripts do not include it in this verse. The central request is dependence on God’s power and protection.", refs: ["Matthew 26:41","John 17:15","1 Chronicles 29:11"] },
  "Matthew 6:14": { title: "Forgive as You Seek Forgiveness", text: "Jesus teaches that those asking God for forgiveness must be willing to forgive others. This does not mean denying wrongdoing; it means refusing to nurture vengeance.", refs: ["Mark 11:25","Ephesians 4:32"] },
  "Matthew 6:15": { title: "The Seriousness of Unforgiveness", text: "Jesus repeats the warning to show that persistent refusal to forgive contradicts the mercy a person asks from God. The verse calls for a heart transformed by grace.", refs: ["Matthew 18:32–35","James 2:13"] },
  "Matthew 6:16": { title: "Fasting Without a Show", text: "Fasting must not be a performance designed to win admiration. Jesus condemns using a spiritual discipline to manufacture a reputation for holiness.", refs: ["Isaiah 58:3–7","Luke 18:12–14"] },
  "Matthew 6:17": { title: "Wash and Anoint Yourself", text: "Jesus instructs the fasting disciple to appear normally rather than advertise the fast. The point is sincerity before God, not a universal rule about grooming.", refs: ["Matthew 6:1","Colossians 3:23"] },
  "Matthew 6:18": { title: "The Father Sees Secret Fasting", text: "The Father sees devotion hidden from people. Jesus emphasizes the motive of the heart rather than promising that every fast will bring a visible reward.", refs: ["Matthew 6:4–6","Hebrews 11:6"] },
  "Matthew 6:19": { title: "Do Not Store Up Earthly Treasures", text: "Earthly wealth can decay or be stolen, so it is an unstable foundation for life. Jesus warns against making possessions the chief purpose of the heart.", refs: ["Proverbs 23:4–5","1 Timothy 6:17"] },
  "Matthew 6:20": { title: "Lay Up Treasure in Heaven", text: "Jesus directs disciples toward lasting spiritual treasure through faithful obedience, generosity, and service to God. Earthly resources can be used for eternal purposes.", refs: ["Matthew 19:21","1 Timothy 6:18–19"] },
  "Matthew 6:21": { title: "Treasure Reveals the Heart", text: "What a person treasures directs their desires and decisions. The disciple should examine whether God’s kingdom or temporary possessions have first place.", refs: ["Luke 12:34","Colossians 3:1–2"] },
  "Matthew 6:22": { title: "The Eye as the Body’s Lamp", text: "Jesus uses the eye as an image of inner focus and perception. A clear, generous outlook helps direct the whole life toward what is good.", refs: ["Luke 11:34–36","Proverbs 22:9"] },
  "Matthew 6:23": { title: "When the Light Is Darkness", text: "A corrupted inner outlook can make a person mistake evil for good. Spiritual blindness is dangerous because it may disguise itself as insight.", refs: ["John 9:39–41","Ephesians 5:8–13"] },
  "Matthew 6:24": { title: "God or Mammon", text: "No one can give ultimate service to both God and wealth. Money may be used responsibly, but it must never become the master that controls loyalty and worship.", refs: ["Joshua 24:15","Luke 16:13"] },
  "Matthew 6:25": { title: "Do Not Be Ruled by Anxiety", text: "Jesus warns against being consumed by worry about food, drink, and clothing. He does not forbid work or planning; He calls disciples to trust God instead of being mastered by fear.", refs: ["Philippians 4:6–7","1 Peter 5:7"] },
  "Matthew 6:26": { title: "Consider the Birds", text: "Birds illustrate God’s sustaining care. The example encourages trust, not idleness; Scripture also teaches responsible work and provision.", refs: ["Psalm 147:9","2 Thessalonians 3:10"] },
  "Matthew 6:27": { title: "Worry Cannot Add to Your Life", text: "Anxiety cannot give human beings control over life’s length or outcomes. Jesus calls for humility about our limits and confidence in God’s care.", refs: ["Luke 12:25–26","Psalm 39:5"] },
  "Matthew 6:28": { title: "Consider the Lilies", text: "The flowers show the beauty God gives to creation without human striving. Jesus invites His hearers to learn trust by observing the world God sustains.", refs: ["Psalm 104:24","Luke 12:27"] },
  "Matthew 6:29": { title: "Solomon’s Glory Compared", text: "Even Solomon’s royal clothing did not surpass the beauty of the flowers. Material splendor is not the measure of God’s care or of a person’s worth.", refs: ["1 Kings 10:4–7","2 Chronicles 9:3–6"] },
  "Matthew 6:30": { title: "God Clothes the Grass", text: "If God clothes grass that soon fades, His people have reason to trust His ability to provide. Jesus challenges anxious unbelief and calls for faith.", refs: ["Isaiah 40:6–8","Luke 12:28"] },
  "Matthew 6:31": { title: "Do Not Be Consumed by Worry", text: "Jesus repeats the warning not to be dominated by concern over necessities. Repetition underlines how easily anxiety can displace trust in God.", refs: ["Matthew 6:25–30","Philippians 4:19"] },
  "Matthew 6:32": { title: "The Nations Seek These Things", text: "Jesus notes that people without confidence in God may be consumed by material needs. The Father already knows what His children require, so fear need not govern them.", refs: ["Psalm 23:1","Matthew 6:8"] },
  "Matthew 6:33": { title: "Seek First the Kingdom", text: "The primary pursuit is God’s kingdom and righteousness. This is a call to put God’s will first, not a promise of luxury or freedom from every hardship.", refs: ["Matthew 5:6","Psalm 37:4–7"] },
  "Matthew 6:34": { title: "Today’s Trouble Is Sufficient", text: "Jesus teaches disciples to meet today faithfully without carrying tomorrow’s imagined burdens in advance. Wise planning is compatible with trust; anxious preoccupation is not.", refs: ["Exodus 16:4–5","James 4:13–15"] }
});
